import numpy as np
import scipy.sparse as sp
import torch
from torch import nn

from recbole.model.general_recommender.bpr import BPR


class FreshCandidateModel(BPR):
    def __init__(self, config, dataset):
        super().__init__(config, dataset)

        self.mechanism_enabled = True
        self.unsigned_transport_enabled = False
        self.embedding_size = int(config["embedding_size"])

        self.register_buffer("user_history_items", self._build_user_history_matrix(dataset))

        pos_graph, neg_graph, unsigned_graph = self._build_signed_graphs(dataset)
        self.register_buffer("pos_graph", self._scipy_to_torch_sparse(pos_graph, self.n_items))
        self.register_buffer("neg_graph", self._scipy_to_torch_sparse(neg_graph, self.n_items))
        self.register_buffer("unsigned_graph", self._scipy_to_torch_sparse(unsigned_graph, self.n_items))

    def set_mechanism_enabled(self, enabled: bool):
        self.mechanism_enabled = bool(enabled)

    def set_unsigned_transport_enabled(self, enabled: bool):
        self.unsigned_transport_enabled = bool(enabled)

    def calculate_loss(self, interaction):
        user = interaction[self.USER_ID]
        pos_item = interaction[self.POS_ITEM_ID]
        neg_item = interaction[self.NEG_ITEM_ID]

        pos_score = self._score(user, pos_item)
        neg_score = self._score(user, neg_item)
        pos_score = torch.nan_to_num(pos_score, nan=0.0, posinf=1e6, neginf=-1e6)
        neg_score = torch.nan_to_num(neg_score, nan=0.0, posinf=1e6, neginf=-1e6)
        return self.loss(pos_score, neg_score)

    def predict(self, interaction):
        user = interaction[self.USER_ID]
        item = interaction[self.ITEM_ID]
        score = self._score(user, item)
        return torch.nan_to_num(score, nan=0.0, posinf=1e6, neginf=-1e6)

    def full_sort_predict(self, interaction):
        user = interaction[self.USER_ID]
        scores = self._full_sort_score(user)
        scores = torch.nan_to_num(scores, nan=0.0, posinf=1e6, neginf=-1e6)
        return scores.view(-1)

    def _score(self, user, item):
        user_e = self.user_embedding(user)
        item_e = self.item_embedding(item)
        direct = torch.sum(user_e * item_e, dim=-1)

        if not self.mechanism_enabled:
            return direct

        if self.unsigned_transport_enabled:
            transport_user = self._user_transport_embedding(user, user_e, mode="unsigned")
            transport = torch.sum(transport_user * item_e, dim=-1)
            return direct + transport

        pos_user = self._user_transport_embedding(user, user_e, mode="pos")
        neg_user = self._user_transport_embedding(user, user_e, mode="neg")
        pos_score = torch.sum(pos_user * item_e, dim=-1)
        neg_score = torch.sum(neg_user * item_e, dim=-1)
        return direct + pos_score - neg_score

    def _full_sort_score(self, user):
        user_e = self.user_embedding(user)
        all_item_e = self.item_embedding.weight
        direct = torch.matmul(user_e, all_item_e.transpose(0, 1))

        if not self.mechanism_enabled:
            return direct

        if self.unsigned_transport_enabled:
            transport_user = self._user_transport_embedding(user, user_e, mode="unsigned")
            transport = torch.matmul(transport_user, all_item_e.transpose(0, 1))
            return direct + transport

        pos_user = self._user_transport_embedding(user, user_e, mode="pos")
        neg_user = self._user_transport_embedding(user, user_e, mode="neg")
        pos_score = torch.matmul(pos_user, all_item_e.transpose(0, 1))
        neg_score = torch.matmul(neg_user, all_item_e.transpose(0, 1))
        return direct + pos_score - neg_score

    def _user_transport_embedding(self, user, user_e, mode="pos"):
        hist_items = self.user_history_items[user]
        hist_mask = hist_items.ne(0)

        if hist_items.size(1) == 0:
            return torch.zeros_like(user_e)

        hist_item_e = self.item_embedding(hist_items)
        gate_logits = torch.sum(hist_item_e * user_e.unsqueeze(1), dim=-1)
        gate_logits = gate_logits.masked_fill(~hist_mask, -1e9)
        gate = torch.softmax(gate_logits, dim=1)
        gate = gate * hist_mask.float()
        gate_sum = gate.sum(dim=1, keepdim=True).clamp_min(1e-12)
        gate = gate / gate_sum

        propagated = self._propagated_item_embeddings(mode)
        hist_prop = propagated[hist_items]
        user_transport = torch.sum(hist_prop * gate.unsqueeze(-1), dim=1)
        return torch.nan_to_num(user_transport, nan=0.0, posinf=1e6, neginf=-1e6)

    def _propagated_item_embeddings(self, mode):
        item_e = self.item_embedding.weight
        if mode == "pos":
            graph = self.pos_graph
        elif mode == "neg":
            graph = self.neg_graph
        else:
            graph = self.unsigned_graph
        return torch.sparse.mm(graph, item_e)

    def _build_user_history_matrix(self, dataset):
        user_histories = self._extract_user_histories(dataset)
        max_len = 0
        for items in user_histories:
            if len(items) > max_len:
                max_len = len(items)
        hist = np.zeros((self.n_users, max_len), dtype=np.int64)
        for u, items in enumerate(user_histories):
            if items:
                hist[u, : len(items)] = np.asarray(items, dtype=np.int64)
        return torch.from_numpy(hist)

    def _build_signed_graphs(self, dataset):
        user_histories = self._extract_user_histories(dataset)
        edge_count = {}
        out_count = np.zeros(self.n_items, dtype=np.float64)
        in_count = np.zeros(self.n_items, dtype=np.float64)

        for items in user_histories:
            if len(items) < 2:
                continue
            for a, b in zip(items[:-1], items[1:]):
                if a == 0 or b == 0:
                    continue
                edge_count[(a, b)] = edge_count.get((a, b), 0.0) + 1.0
                edge_count[(b, a)] = edge_count.get((b, a), 0.0) + 1.0
                out_count[a] += 1.0
                in_count[b] += 1.0
                out_count[b] += 1.0
                in_count[a] += 1.0

        total_transitions = float(out_count.sum())
        pos_rows, pos_cols, pos_vals = [], [], []
        neg_rows, neg_cols, neg_vals = [], [], []
        uns_rows, uns_cols, uns_vals = [], [], []

        if total_transitions <= 0.0:
            empty = sp.coo_matrix((self.n_items, self.n_items), dtype=np.float32)
            return empty, empty, empty

        for (i, j), c in edge_count.items():
            expected = (out_count[i] * in_count[j]) / total_transitions if total_transitions > 0.0 else 0.0
            residual = c - expected
            if residual > 0.0:
                pos_rows.append(i)
                pos_cols.append(j)
                pos_vals.append(residual)
            elif residual < 0.0:
                neg_rows.append(i)
                neg_cols.append(j)
                neg_vals.append(-residual)
            mag = abs(residual)
            if mag > 0.0:
                uns_rows.append(i)
                uns_cols.append(j)
                uns_vals.append(mag)

        pos = sp.coo_matrix((np.asarray(pos_vals, dtype=np.float32), (np.asarray(pos_rows), np.asarray(pos_cols))), shape=(self.n_items, self.n_items), dtype=np.float32)
        neg = sp.coo_matrix((np.asarray(neg_vals, dtype=np.float32), (np.asarray(neg_rows), np.asarray(neg_cols))), shape=(self.n_items, self.n_items), dtype=np.float32)
        uns = sp.coo_matrix((np.asarray(uns_vals, dtype=np.float32), (np.asarray(uns_rows), np.asarray(uns_cols))), shape=(self.n_items, self.n_items), dtype=np.float32)

        return self._row_normalize(pos), self._row_normalize(neg), self._row_normalize(uns)

    def _extract_user_histories(self, dataset):
        uid = self._to_numpy(dataset.inter_feat[self.USER_ID]).astype(np.int64)
        iid = self._to_numpy(dataset.inter_feat[self.ITEM_ID]).astype(np.int64)

        time_field = getattr(dataset, "time_field", None)
        if time_field is not None and time_field in dataset.inter_feat:
            t = self._to_numpy(dataset.inter_feat[time_field])
            order = np.lexsort((t, uid))
        else:
            order = np.argsort(uid, kind="mergesort")

        uid = uid[order]
        iid = iid[order]

        histories = [[] for _ in range(self.n_users)]
        last_user = -1
        seen = None
        for u, i in zip(uid, iid):
            if u <= 0 or i <= 0:
                continue
            if u != last_user:
                last_user = int(u)
                seen = set()
            if i not in seen:
                histories[int(u)].append(int(i))
                seen.add(int(i))
        return histories

    @staticmethod
    def _to_numpy(x):
        if isinstance(x, torch.Tensor):
            return x.detach().cpu().numpy()
        return np.asarray(x)

    @staticmethod
    def _row_normalize(matrix):
        matrix = matrix.tocsr()
        row_sum = np.asarray(matrix.sum(axis=1)).reshape(-1)
        inv = np.zeros_like(row_sum, dtype=np.float32)
        nonzero = row_sum > 0
        inv[nonzero] = 1.0 / row_sum[nonzero]
        d_inv = sp.diags(inv)
        return (d_inv @ matrix).tocoo().astype(np.float32)

    @staticmethod
    def _scipy_to_torch_sparse(matrix, size):
        matrix = matrix.tocoo()
        if matrix.nnz == 0:
            indices = torch.zeros((2, 0), dtype=torch.long)
            values = torch.zeros((0,), dtype=torch.float32)
            return torch.sparse_coo_tensor(indices, values, (size, size)).coalesce()
        indices = torch.from_numpy(np.vstack((matrix.row, matrix.col)).astype(np.int64))
        values = torch.from_numpy(matrix.data.astype(np.float32))
        return torch.sparse_coo_tensor(indices, values, (size, size)).coalesce()
